import React, { useEffect, useState, useMemo } from 'react';
import { Link } from 'react-router-dom';
import Chart from 'react-apexcharts';
import { useSelector } from 'react-redux';
import { ref, onValue } from 'firebase/database';
import { database } from '../components/Firebase/firebaseConfig';

import StatusCard from '../components/status-card/StatusCard';
import Table from '../components/table/Table';
import Badge from '../components/badge/Badge';

const chartData = {
    series: [{
        name: 'Hoạt động',
        data: [40, 70, 20, 90, 36, 80, 30, 91, 60, 50, 45, 75]
    }, {
        name: 'Sản phẩm',
        data: [40, 30, 70, 80, 40, 16, 40, 20, 51, 10, 65, 35]
    }],
    options: {
        colors: ['#6ab04c', '#2980b9'],
        chart: { background: 'transparent' },
        dataLabels: { enabled: false },
        stroke: { curve: 'smooth' },
        xaxis: {
            categories: ['Tháng 1', 'Tháng 2', 'Tháng 3', 'Tháng 4', 'Tháng 5', 'Tháng 6', 
                         'Tháng 7', 'Tháng 8', 'Tháng 9', 'Tháng 10', 'Tháng 11', 'Tháng 12']
        },
        legend: { position: 'top' },
        grid: { show: false }
    }
};

const Dashboard = () => {
    const themeReducer = useSelector(state => state.ThemeReducer.mode);

    const [totalCustomers, setTotalCustomers] = useState(0);
    const [totalProducts, setTotalProducts] = useState(0);
    const [totalOrders, setTotalOrders] = useState(0);
    const [topCustomers, setTopCustomers] = useState([]);
    const [latestOrders, setLatestOrders] = useState([]);

    useEffect(() => {
        // 🧩 Lấy khách hàng
        const usersRef = ref(database, 'Users');
        onValue(usersRef, (snapshot) => {
            const data = snapshot.val();
            if (data) {
                const customers = Object.entries(data).map(([id, user]) => {
                    let totalOrders = 0;
                    let totalSpend = 0;
                    if (user.orders) {
                        const orders = Object.values(user.orders);
                        totalOrders = orders.length;
                        totalSpend = orders.reduce((sum, o) => sum + (o.total || 0), 0);
                    }
                    return {
                        username: user.profile_name || 'Không có tên',
                        total_orders: totalOrders,
                        total_spend: totalSpend
                    };
                });
                setTotalCustomers(customers.length);
                const sorted = customers
                    .sort((a, b) => b.total_spend - a.total_spend)
                    .slice(0, 5);
                setTopCustomers(sorted);
            }
        });

        // 🧩 Lấy sản phẩm
        const itemsRef = ref(database, 'Items');
        onValue(itemsRef, (snapshot) => {
            const data = snapshot.val();
            if (data) {
                const products = Object.values(data);
                setTotalProducts(products.length);
            }
        });

        // 🧩 Lấy đơn hàng
        onValue(usersRef, (snapshot) => {
            const data = snapshot.val();
            if (data) {
                let allOrders = [];
                Object.entries(data).forEach(([userId, userData]) => {
                    if (userData.orders) {
                        Object.entries(userData.orders).forEach(([orderId, order]) => {
                            allOrders.push({
                                id: orderId,
                                user: userData.profile_name,
                                total: order.total || 0,
                                date: order.date || 'Không rõ',
                                status: order.status || 'Chờ xử lý'
                            });
                        });
                    }
                });
                setTotalOrders(allOrders.length);
                const sorted = allOrders
                    .sort((a, b) => b.date.localeCompare(a.date))
                    .slice(0, 5);
                setLatestOrders(sorted);
            }
        });
    }, []);

    const chartOptions = useMemo(() => ({
        ...chartData.options,
        theme: { mode: themeReducer === 'theme-mode-dark' ? 'dark' : 'light' }
    }), [themeReducer]);

    const orderStatus = {
        'Đang giao': 'primary',
        'Chờ xử lý': 'warning',
        'Đã giao': 'success',
        'Đã huỷ': 'danger'
    };

    const renderCustomerHead = (item, index) => <th key={index}>{item}</th>;
    const renderCustomerBody = (item, index) => (
        <tr key={index}>
            <td>{item.username}</td>
            <td>{item.total_orders}</td>
            <td>{item.total_spend.toLocaleString()} VND</td>
        </tr>
    );

    const renderOrderHead = (item, index) => <th key={index}>{item}</th>;
    const renderOrderBody = (item, index) => (
        <tr key={index}>
            <td>{item.id}</td>
            <td>{item.user}</td>
            <td>{item.total.toLocaleString()} VND</td>
            <td>{item.date}</td>
            <td><Badge type={orderStatus[item.status] || 'warning'} content={item.status} /></td>
        </tr>
    );

    const statusCards = [
        { icon: "bx bx-user", count: totalCustomers, title: "Khách hàng" },
        { icon: "bx bx-cart", count: totalOrders, title: "Đơn hàng" },
        { icon: "bx bx-box", count: totalProducts, title: "Sản phẩm" },
        { icon: "bx bx-dollar", count: topCustomers.reduce((a, b) => a + b.total_spend, 0).toLocaleString(), title: "Doanh thu (Top 5)" }
    ];

    return (
        <div>
            <h2 className="page-header">Dashboard</h2>
            <p style={{ marginBottom: "20px", fontWeight: "500", fontSize: "16px" }}>
                Chào mừng bạn đến với trang quản trị của shop!
            </p>

            <div className="row">
                <div className="col-12">
                    <div className="row">
                        <div className="col-6">
                            <div className="row">
                                {statusCards.map((item, index) => (
                                    <div className="col-6" key={index}>
                                        <StatusCard icon={item.icon} count={item.count} title={item.title} />
                                    </div>
                                ))}
                            </div>
                        </div>

                        <div className="col-6">
                            <div className="card full-height">
                                <Chart
                                    options={chartOptions}
                                    series={chartData.series}
                                    type='line'
                                    height='100%'
                                />
                            </div>
                        </div>
                    </div>
                </div>

                <div className="col-12">
                    <div className="row">
                        <div className="col-6">
                            <div className="card">
                                <div className="card__header"><h3>Khách hàng top</h3></div>
                                <div className="card__body">
                                    <Table
                                        headData={['Người dùng', 'Tổng đơn hàng', 'Tổng chi tiêu']}
                                        renderHead={renderCustomerHead}
                                        bodyData={topCustomers}
                                        renderBody={renderCustomerBody}
                                    />
                                </div>
                                <div className="card__footer"><Link to='/customers'>Xem tất cả</Link></div>
                            </div>
                        </div>

                        <div className="col-6">
                            <div className="card">
                                <div className="card__header"><h3>Đơn hàng mới nhất</h3></div>
                                <div className="card__body">
                                    <Table
                                        headData={['Mã ĐH', 'Người dùng', 'Tổng tiền', 'Ngày', 'Trạng thái']}
                                        renderHead={renderOrderHead}
                                        bodyData={latestOrders}
                                        renderBody={renderOrderBody}
                                    />
                                </div>
                                <div className="card__footer"><Link to='/orders'>Xem tất cả</Link></div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
